<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">authorizer.class.name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=org.apache.kafka.metadata.authorizer.StandardAuthorizer</span></span>
